-- Syncs the live checklist tables to src/data/catalog.json (the catalog the app ships).
-- Matches lists by slug, sections by list + slug, and items by permanent_key, so existing progress keeps its item IDs.
-- Supersedes the catalog parts of 0019, 0022, and 0023 on databases that skipped them.

begin;

alter table public.checklist_items add column if not exists quick_start boolean not null default false;
alter table public.checklist_items add column if not exists item_type text not null default 'core';
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'checklist_items_item_type_check') then
    alter table public.checklist_items add constraint checklist_items_item_type_check check (item_type in ('core', 'extended', 'vault'));
  end if;
end $$;




-- Items removed from the catalog stay in place for past progress but can no longer be checked.
update public.checklist_items set active = false
where active and permanent_key not in (
  'grab.communication.phone',
  'grab.communication.powerbank',
